        & (io_stall ? bits_ctrl_is_alu_op : io_in_valid & io_in_bits_ctrl_is_alu_op);
      bits_ctrl_is_csr <=
        ~io_flush & (io_stall ? bits_ctrl_is_csr : io_in_valid & io_in_bits_ctrl_is_csr);
      if (io_flush) begin
        bits_imm <= 32'h0;
        bits_rs1_addr <= 5'h0;
        bits_rs2_addr <= 5'h0;
        bits_rs1_val <= 32'h0;
        bits_rs2_val <= 32'h0;
        bits_pc <= 32'h0;
        bits_rd <= 5'h0;
        bits_inst <= 32'h0;
        bits_pred_gsh_idx <= 8'h0;
        bits_pred_loc_hist <= 6'h0;
        bits_pred_pred_target <= 32'h0;
      end
      else if (io_stall) begin
        if (valid) begin
          bits_rs1_val <= io_refresh_rs1_val;
          bits_rs2_val <= io_refresh_rs2_val;
        end
      end
      else begin
        bits_imm <= io_in_valid ? io_in_bits_imm : 32'h0;
        bits_rs1_addr <= io_in_valid ? io_in_bits_rs1_addr : 5'h0;
        bits_rs2_addr <= io_in_valid ? io_in_bits_rs2_addr : 5'h0;
        bits_rs1_val <= io_in_valid ? io_in_bits_rs1_val : 32'h0;
        bits_rs2_val <= io_in_valid ? io_in_bits_rs2_val : 32'h0;
        bits_pc <= io_in_valid ? io_in_bits_pc : 32'h0;
        bits_rd <= io_in_valid ? io_in_bits_rd : 5'h0;
        bits_inst <= io_in_valid ? io_in_bits_inst : 32'h0;
        bits_pred_gsh_idx <= io_in_valid ? io_in_bits_pred_gsh_idx : 8'h0;
        bits_pred_loc_hist <= io_in_valid ? io_in_bits_pred_loc_hist : 6'h0;
        bits_pred_pred_target <= io_in_valid ? io_in_bits_pred_pred_target : 32'h0;
      end
      bits_is_stall <=
        ~io_flush & (io_stall ? bits_is_stall : io_in_valid & io_in_bits_is_stall);
      bits_pred_taken <=
        ~io_flush & (io_stall ? bits_pred_taken : io_in_valid & io_in_bits_pred_taken);
      bits_pred_gsh_pred <=
        ~io_flush
        & (io_stall ? bits_pred_gsh_pred : io_in_valid & io_in_bits_pred_gsh_pred);
      bits_pred_loc_pred <=
        ~io_flush
        & (io_stall ? bits_pred_loc_pred : io_in_valid & io_in_bits_pred_loc_pred);
    end
  end // always @(posedge)
